        FastScanner fs = new FastScanner();
        int S = fs.nextInt();
        int T = fs.nextInt();

        boolean[][] adj = new boolean[S + 1][S + 1];

        for (int i = 0; i < T; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            adj[x][y] = true;
            adj[y][x] = true;
        }

        int P = fs.nextInt();
        int answer = 0;

        for (int p = 0; p < P; p++) {
            int N = fs.nextInt();
            int prev = fs.nextInt();
            boolean possible = true;

            for (int i = 1; i < N; i++) {
                int cur = fs.nextInt();
                if (possible && !adj[prev][cur]) {
                    possible = false;
                }
                prev = cur;
            }

            if (possible) {
                answer++;
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int nextByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = nextByte();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextByte();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = nextByte();
            }

            return value * sign;
        }
    }
}
